export const QUESTIONS_442A = [
  // ═══ BLOCK A: Common Occupational Skills (20) ═══
  {id:1,cat:"A",q:"What is the minimum PPE for working near exposed energized 480V equipment?",opts:["Arc-rated clothing, face shield, insulated gloves rated for voltage","Safety glasses only","Hard hat and steel toes only","Rubber boots"],ans:0,exp:"Working near 480V requires arc flash PPE per CSA Z462 — arc-rated clothing, face shield, voltage-rated insulated gloves. An arc flash risk assessment determines the specific category.",type:"procedure"},
  {id:2,cat:"A",q:"When performing the live-dead-live test before maintenance, what is the correct sequence?",opts:["Test circuit, verify meter works","Verify meter on known live source, test circuit dead, verify meter on known live again","Test circuit, then verify meter","Just test the circuit once"],ans:1,exp:"Live-dead-live: (1) Prove tester works on known live source, (2) Test target circuit to confirm dead, (3) Prove tester still works on known live source. This verifies your tester wasn't faulty.",type:"procedure"},
  {id:3,cat:"A",q:"CSA Z462 requires an energized work permit when:",opts:["Always","For any voltage over 120V","When de-energizing creates a greater hazard or is infeasible","Only for work above 600V"],ans:2,exp:"Energized work permits are required when de-energizing creates a greater hazard (life support, continuous process) or is demonstrated to be infeasible. De-energizing is always the first choice.",type:"recall"},
  {id:4,cat:"A",q:"A confined space in an industrial electrical context requires:",opts:["A hard hat only","Just a flashlight","Supervisor notification only","Atmospheric testing, entry permit, standby person, and rescue plan"],ans:3,exp:"Confined spaces (transformer vaults, manholes, cable trenches) require atmospheric testing (O2, LEL, toxics), entry permits, a standby attendant, and a rescue plan.",type:"procedure"},
  {id:5,cat:"A",q:"What is the purpose of a Job Safety Analysis (JSA) before electrical work?",opts:["Identify hazards for each step and determine control measures","To assign blame","Satisfy paperwork requirements only","Calculate labour costs"],ans:0,exp:"A JSA breaks the job into steps, identifies hazards at each step, and determines controls (elimination, engineering, PPE). It's a critical pre-task planning tool.",type:"recall"},
  {id:6,cat:"A",q:"In an industrial setting, who can perform electrical work?",opts:["Anyone with basic training","Only licensed electricians or supervised apprentices","Any maintenance worker","Engineers only"],ans:1,exp:"Only licensed electricians (journeypersons) or registered apprentices under direct supervision may perform electrical work per provincial regulations.",type:"recall"},
  {id:7,cat:"A",q:"An electrical single-line diagram shows:",opts:["Detailed wiring connections","Only motor controls","Simplified representation of the power distribution system using single lines","Only lighting circuits"],ans:2,exp:"Single-line (one-line) diagrams show the overall power distribution using simplified symbols — transformers, switchgear, breakers, feeders — without showing every conductor.",type:"recall"},
  {id:8,cat:"A",q:"What information does a motor nameplate provide?",opts:["Only HP and voltage","Only the manufacturer","Only the serial number","HP, voltage, FLA, RPM, frame, efficiency, service factor, enclosure type, and more"],ans:3,exp:"Nameplate data is critical: HP, voltage, phases, FLA, RPM, frame size, efficiency, service factor, enclosure (TEFC, ODP), insulation class, design letter, and connection diagram.",type:"recall"},
  {id:9,cat:"A",q:"When reading a P&ID (Piping & Instrumentation Diagram), a circle with a line through it represents:",opts:["A field-mounted instrument","A valve","A control panel-mounted instrument","A pump"],ans:0,exp:"ISA symbology: circle = instrument. Line through center = panel-mounted. No line = field-mounted. Square = DCS/PLC function. The letters inside identify the function (TT=temperature transmitter).",type:"recall"},
  {id:10,cat:"A",q:"The CEC Section that covers industrial installations is:",opts:["Section 10","Section 26","Section 28","Section 36"],ans:1,exp:"CEC Section 26 covers installation of electrical equipment in industrial establishments, including motor installations, industrial control, and related equipment.",type:"recall"},
  {id:11,cat:"A",q:"What does NFPA 70E (or CSA Z462 equivalent) primarily address?",opts:["Electrical installation standards","Fire alarm systems","Electrical safety in the workplace — protecting workers from electrical hazards","Lightning protection"],ans:2,exp:"CSA Z462 (Canadian equivalent of NFPA 70E) establishes requirements for electrical safety-related work practices to protect workers from shock and arc flash hazards.",type:"recall"},
  {id:12,cat:"A",q:"When using a megohmmeter on a motor, the test voltage should be:",opts:["Always 500V","Equal to the motor voltage","1000V always","Based on the motor's rated voltage per IEEE/CSA guidelines"],ans:3,exp:"Test voltage depends on motor rating: <1000V motors = 500V or 1000V test. 1000-2500V = 2500V test. Testing at too high voltage can damage insulation.",type:"procedure"},
  {id:13,cat:"A",q:"The minimum insulation resistance for a motor rated under 1000V is approximately:",opts:["1 MΩ minimum, but 100 MΩ+ is healthy","1 kΩ","100Ω","10 GΩ"],ans:0,exp:"Minimum acceptable is typically 1MΩ + 1MΩ per kV of rated voltage. For a 480V motor: minimum ~1.5MΩ. Healthy motors read 100MΩ or more. Below minimum = investigate.",type:"recall"},
  {id:14,cat:"A",q:"What is the purpose of equipment grounding in an industrial facility?",opts:["Improve power quality","Provide a low-impedance fault current path to trip overcurrent devices and prevent shock","Reduce power consumption","Balance phases"],ans:1,exp:"Equipment grounding provides a low-impedance path for fault current to flow back to the source, causing the overcurrent device to trip quickly and preventing dangerous touch voltages.",type:"recall"},
  {id:15,cat:"A",q:"When installing cable tray in an industrial facility, the fill must not exceed:",opts:["100%","25%","The maximum fill per CEC Section 12","10%"],ans:2,exp:"CEC Section 12 specifies cable tray fill based on cable type and tray configuration. Single-layer for large cables, depth-limited fill for smaller cables. Never overload trays.",type:"recall"},
  {id:16,cat:"A",q:"TECK cable is commonly used in industrial installations because:",opts:["It's cheapest","It's flexible like cord","It doesn't need supports","It provides mechanical protection, moisture resistance, and grounding via the interlocking armor"],ans:3,exp:"TECK cable has: copper conductors, insulation, shield, interlocking aluminum armor (mechanical protection + grounding), and PVC jacket (moisture). Ideal for industrial environments.",type:"recall"},
  {id:17,cat:"A",q:"When commissioning a new motor installation, what must be checked before first start?",opts:["Rotation direction (bump test), alignment, lubrication, connections, insulation resistance, and overcurrent settings","Paint colour","Only the voltage","Only the nameplate"],ans:0,exp:"Pre-commissioning checklist: insulation resistance test, connection verification, alignment check, lubrication, bump test for rotation, overcurrent device sizing, and grounding verification.",type:"procedure"},
  {id:18,cat:"A",q:"What is the danger of a floating neutral in a 3-phase wye system?",opts:["No danger","Voltage imbalance causing overvoltage on lightly loaded phases (can exceed 200V on 120V circuits)","Reduced power only","Increased efficiency"],ans:1,exp:"A floating (disconnected) neutral allows the neutral point to shift, causing severe voltage imbalance. Lightly loaded phases see dangerously high voltage, destroying 120V equipment.",type:"critical"},
  {id:19,cat:"A",q:"Industrial receptacles rated 30A and above typically use what configuration?",opts:["Standard duplex","Standard 15A with adapter","Pin-and-sleeve (IEC 60309) or twist-lock (NEMA locking)","USB-C"],ans:2,exp:"Industrial environments use pin-and-sleeve (IEC) or NEMA locking receptacles rated 30A+ for reliability, safety, and resistance to accidental disconnection in vibrating environments.",type:"recall"},
  {id:20,cat:"A",q:"What is a typical grounding electrode resistance target for an industrial facility?",opts:["100Ω","50Ω","25Ω","5Ω or less"],ans:3,exp:"Most industrial standards target 5Ω or less for the grounding electrode system. Lower is better. Achieved through ground rods, ground rings, concrete-encased electrodes, or chemical grounding.",type:"recall"},

  // ═══ BLOCK B: Electrical Fundamentals & Instrumentation (25) ═══
  {id:21,cat:"B",q:"A 4-20mA signal reads 12mA. If the range is 0-100 PSI, what is the pressure?",opts:["50 PSI","30 PSI","75 PSI","12 PSI"],ans:0,exp:"12mA is at the midpoint of 4-20mA range: (12-4)÷(20-4) = 8÷16 = 50%. 50% of 0-100 PSI = 50 PSI. Formula: Value = ((mA-4)/16) × span + zero.",type:"critical"},
  {id:22,cat:"B",q:"What type of sensor detects metal objects without physical contact?",opts:["Photoelectric","Inductive proximity sensor","Thermocouple","Strain gauge"],ans:1,exp:"Inductive proximity sensors detect ferrous and non-ferrous metals using an oscillating electromagnetic field. No physical contact = no wear. Used extensively for position sensing in industry.",type:"recall"},
  {id:23,cat:"B",q:"An RTD measures temperature based on:",opts:["Voltage generation","Colour change","Change in resistance with temperature","Expansion of a fluid"],ans:2,exp:"RTDs (Resistance Temperature Detectors) use the predictable change in electrical resistance of metals (usually platinum - Pt100) with temperature. More accurate and stable than thermocouples.",type:"recall"},
  {id:24,cat:"B",q:"A Wheatstone bridge circuit is used in instrumentation to:",opts:["Amplify signals","Generate AC power","Convert AC to DC","Precisely measure small changes in resistance (strain gauges, RTDs)"],ans:3,exp:"Wheatstone bridges detect tiny resistance changes with high precision. When balanced, output = 0. Small resistance changes create a proportional voltage output.",type:"recall"},
  {id:25,cat:"B",q:"In a 480/277V 3-phase wye system, 277V is measured between:",opts:["Phase to neutral","Phase to phase","Neutral to ground","Phase to ground"],ans:0,exp:"In 480Y/277V: 480V phase-to-phase, 277V phase-to-neutral. 277V is commonly used for industrial lighting. 480÷√3 = 277V.",type:"recall"},
  {id:26,cat:"B",q:"What is the power consumed by a 480V, 3-phase motor drawing 50A at 0.85 PF?",opts:["24 kW","35.3 kW","40.8 kW","20.4 kW"],ans:1,exp:"P = √3 × V × I × PF = 1.732 × 480 × 50 × 0.85 = 35,294W ≈ 35.3 kW.",type:"critical"},
  {id:27,cat:"B",q:"A current transformer (CT) with a 200:5 ratio on a conductor carrying 150A outputs:",opts:["7.5A","30A","3.75A","150A"],ans:2,exp:"CT output = Primary current × (Secondary ratio ÷ Primary ratio) = 150 × (5÷200) = 3.75A. CTs step down current proportionally for metering.",type:"critical"},
  {id:28,cat:"B",q:"What happens if a CT secondary is left open while the primary is energized?",opts:["Nothing","CT stops working quietly","Current increases","Dangerous high voltage develops across the secondary, potentially lethal"],ans:3,exp:"An open CT secondary develops extremely high voltage (potentially thousands of volts) and saturates the core. This is lethal and destroys the CT. Always short the secondary before disconnecting.",type:"critical"},
  {id:29,cat:"B",q:"A thermocouple works on what principle?",opts:["Seebeck effect — voltage generated at junction of two dissimilar metals","Resistance change","Capacitance change","Magnetic induction"],ans:0,exp:"Thermocouples generate a small voltage (millivolts) at the junction of two dissimilar metals proportional to temperature. Types: J, K, T, E, S — each for different temperature ranges.",type:"recall"},
  {id:30,cat:"B",q:"A capacitive proximity sensor detects:",opts:["Only metals","Metals, liquids, plastics, granular materials — most materials","Only ferrous metals","Only moving objects"],ans:1,exp:"Capacitive sensors detect changes in the dielectric field — any material that changes capacitance: metals, plastics, glass, liquids, powders. More versatile than inductive sensors.",type:"recall"},
  {id:31,cat:"B",q:"What does a power factor correction capacitor bank do?",opts:["Store energy for backup","Increase voltage","Reduce reactive power demand, improving PF and reducing utility penalties","Generate power"],ans:2,exp:"Capacitor banks supply reactive power locally, reducing the reactive current drawn from the utility. This improves power factor, reduces losses, and avoids utility PF penalties.",type:"recall"},
  {id:32,cat:"B",q:"The harmonics most commonly produced by VFDs are:",opts:["Even harmonics (2nd, 4th)","DC offset","Subharmonics","Odd harmonics (5th, 7th, 11th, 13th)"],ans:3,exp:"6-pulse VFDs generate 5th, 7th, 11th, 13th harmonics (h = 6n±1). 12-pulse drives eliminate 5th and 7th. Harmonics cause overheating of transformers, motors, and conductors.",type:"critical"},
  {id:33,cat:"B",q:"A SCADA system is used for:",opts:["Supervisory control and data acquisition — monitoring and controlling industrial processes remotely","Motor starting only","Email communication","Lighting control only"],ans:0,exp:"SCADA collects data from remote instruments and PLCs, displays process status, allows operator control, logs data, and generates alarms. Used in utilities, oil/gas, water treatment.",type:"recall"},
  {id:34,cat:"B",q:"An ultrasonic level sensor measures tank level by:",opts:["Weighing the tank","Measuring the time for a sound pulse to travel to the surface and back","Measuring pressure","Measuring capacitance"],ans:1,exp:"Ultrasonic sensors emit a sound pulse, measure the time to the reflection from the liquid surface, and calculate distance. Non-contact, no moving parts.",type:"recall"},
  {id:35,cat:"B",q:"What is the typical output signal from a pressure transmitter?",opts:["0-5V DC only","120V AC","4-20mA DC (most common industrial standard)","Digital pulses only"],ans:2,exp:"4-20mA is the dominant industrial standard. Advantages: immune to wire resistance (current loop), 4mA live zero detects broken wires, powered by the loop (2-wire).",type:"recall"},
  {id:36,cat:"B",q:"Short circuit current in an industrial facility is determined by:",opts:["The size of the motor","The length of the building","The number of lights","The impedance of the entire system from the utility transformer to the fault point"],ans:3,exp:"Available fault current depends on utility contribution, transformer impedance, conductor impedance, and motor contribution. Calculations determine required equipment AIC ratings.",type:"critical"},
  {id:37,cat:"B",q:"A differential pressure transmitter across an orifice plate measures:",opts:["Flow rate","Temperature","Level only","Viscosity"],ans:0,exp:"An orifice plate creates a pressure drop proportional to flow². The DP transmitter measures this differential pressure and the flow computer calculates flow rate using Bernoulli's principle.",type:"recall"},
  {id:38,cat:"B",q:"Ground fault on an ungrounded (floating) delta system is detected by:",opts:["Standard breaker","Ground detection lights or zero-sequence CT ground fault relay","Phase rotation meter","Voltmeter only"],ans:1,exp:"Ungrounded delta systems don't trip on the first ground fault. Ground detection lights (3 lamps to ground) or zero-sequence CTs detect the faulted phase for maintenance.",type:"recall"},
  {id:39,cat:"B",q:"Impedance grounding of a transformer neutral limits:",opts:["Voltage","Power consumption","Ground fault current to a safe level while maintaining ground detection","Harmonics"],ans:2,exp:"Impedance (resistance or reactance) grounding limits ground fault current to reduce arc flash energy and equipment damage while still allowing ground fault relaying to detect and clear faults.",type:"recall"},
  {id:40,cat:"B",q:"A Rogowski coil measures:",opts:["Voltage","Temperature","Resistance","AC current without a solid core — flexible, for large or irregular conductors"],ans:3,exp:"Rogowski coils are flexible current sensors that clip around conductors. No iron core means no saturation. Ideal for measuring large, high-frequency, or transient currents.",type:"recall"},
  {id:41,cat:"B",q:"What is the main advantage of fibre optic communication in industrial settings?",opts:["Immune to electromagnetic interference and capable of very long distances","Cheaper than copper","Easier to terminate","Carries power and data"],ans:0,exp:"Fibre optic is immune to EMI/RFI (critical near VFDs, arc furnaces, and high-voltage equipment), supports very long distances with no signal degradation, and provides electrical isolation.",type:"recall"},
  {id:42,cat:"B",q:"A control valve positioner ensures:",opts:["The valve stays closed","The valve position accurately follows the control signal despite friction and process forces","Maximum flow always","Minimum pressure"],ans:1,exp:"Positioners compare the control signal to actual valve position (feedback) and adjust air pressure to the actuator until the valve reaches the exact demanded position. Eliminates hysteresis and stiction.",type:"recall"},
  {id:43,cat:"B",q:"In a PID control loop, the 'I' (integral) term corrects:",opts:["Rapid changes","Noise","Steady-state offset (sustained error between setpoint and process variable)","Future predicted error"],ans:2,exp:"Integral action sums the error over time, increasing output until the offset is eliminated. It corrects the persistent droop that proportional-only control leaves. Too much I = oscillation.",type:"recall"},
  {id:44,cat:"B",q:"An encoder on a motor shaft provides:",opts:["Lubrication","Overcurrent protection","Thermal protection","Precise position and/or speed feedback to the drive or PLC"],ans:3,exp:"Encoders provide rotational position (absolute) or speed/direction (incremental) feedback. Essential for servo systems, positioning applications, and closed-loop speed control.",type:"recall"},
  {id:45,cat:"B",q:"When calibrating a 4-20mA transmitter, the zero and span adjustments set:",opts:["4mA = zero (LRV) and 20mA = span (URV) of the measurement range","The wire size","The supply voltage","The loop resistance"],ans:0,exp:"Zero adjustment sets the 4mA output at the Lower Range Value. Span sets 20mA at the Upper Range Value. A 5-point calibration checks 0%, 25%, 50%, 75%, and 100% of range.",type:"procedure"},

  // ═══ BLOCK C: Industrial Wiring & Distribution (22) ═══
  {id:46,cat:"C",q:"What is the standard voltage for most industrial motor circuits in Canada?",opts:["120V","480V (or 600V in Canada)","208V","347V"],ans:1,exp:"Canada commonly uses 600V for industrial motors (vs 480V in the US). Higher voltage = lower current = smaller wire for the same power. 600V class equipment is standard in Canadian plants.",type:"recall"},
  {id:47,cat:"C",q:"Cable tray is classified as a wiring method in CEC Section:",opts:["Section 8","Section 10","Section 12","Section 22"],ans:2,exp:"CEC Section 12 covers cable tray as a support system for cables and raceways. It specifies fill limits, cable types allowed, bonding requirements, and installation methods.",type:"recall"},
  {id:48,cat:"C",q:"What type of conduit is best suited for corrosive industrial environments?",opts:["EMT","Rigid steel (RGS)","Flex conduit","PVC-coated rigid steel or Schedule 80 PVC"],ans:3,exp:"PVC-coated rigid galvanized steel provides mechanical strength plus corrosion resistance. Schedule 80 PVC is also used for corrosive environments but lacks mechanical impact resistance of metal.",type:"recall"},
  {id:49,cat:"C",q:"An MCC (Motor Control Center) is:",opts:["A modular assembly housing multiple motor starters, breakers, and controls in a common enclosure","A single motor starter","A generator room","A PLC cabinet"],ans:0,exp:"MCCs contain standardized plug-in units (buckets) with starters, breakers, VFDs, and controls. Each bucket can be withdrawn for maintenance without de-energizing the entire MCC.",type:"recall"},
  {id:50,cat:"C",q:"The purpose of power factor correction at an MCC is:",opts:["Increase motor speed","Reduce reactive power, lower current draw on feeders, and avoid utility penalties","Improve motor starting","Increase voltage"],ans:1,exp:"PF correction caps at the MCC reduce reactive current flowing through upstream feeders and transformers, freeing capacity and reducing I²R losses. Utility PF penalties typically start below 0.9.",type:"recall"},
  {id:51,cat:"C",q:"When selecting wire for a 100A feeder run of 60 metres, you must consider:",opts:["Only ampacity","Only the distance","Ampacity, voltage drop, ambient temperature, and bundling derating factors","Only the conduit size"],ans:2,exp:"All four factors affect conductor sizing. You may need to upsize from the ampacity table to meet the 3% voltage drop limit over 60m. Ambient temp and bundling require derating.",type:"procedure"},
  {id:52,cat:"C",q:"A busway (bus duct) system is used in industrial facilities for:",opts:["Data communication","Grounding only","Lighting circuits only","High-current power distribution with flexibility for tap-off connections"],ans:3,exp:"Busway provides high-current distribution (400A-5000A+) with plug-in tap-off units that allow easy connection/relocation of loads along the run. Common in manufacturing plants.",type:"recall"},
  {id:53,cat:"C",q:"What is the minimum bending radius for TECK 90 cable?",opts:["12× cable OD","3× cable OD","6× cable OD","No limit"],ans:0,exp:"Interlocked armor cable like TECK requires minimum 12× OD bending radius to avoid damaging the interlocking armor and internal conductors. Tighter bends crack the armor.",type:"recall"},
  {id:54,cat:"C",q:"An industrial transfer switch between utility and generator power must provide:",opts:["Parallel operation","Complete isolation — break-before-make to prevent backfeed","Manual operation only","Only generator disconnect"],ans:1,exp:"Transfer switches must be break-before-make (open-transition): disconnect utility BEFORE connecting generator. This prevents backfeed that could kill utility workers.",type:"procedure"},
  {id:55,cat:"C",q:"What is the purpose of a surge arrester on an industrial power system?",opts:["Regulate voltage continuously","Filter harmonics","Clamp transient overvoltages from lightning or switching to protect equipment insulation","Correct power factor"],ans:2,exp:"Surge arresters divert transient energy to ground and clamp voltage to safe levels. Essential on exposed distribution systems and at transformer primaries/secondaries.",type:"recall"},
  {id:56,cat:"C",q:"When installing parallel conductors per phase, all conductors must be:",opts:["Different sizes for load balancing","Different types to reduce harmonics","Copper and aluminum mixed","The same size, type, length, and routed together"],ans:3,exp:"Parallel conductors must be identical (size, type, length, routing) to ensure equal current sharing. Unequal impedance causes one conductor to carry more current, potentially overloading it.",type:"procedure"},
  {id:57,cat:"C",q:"A ground bus in an industrial facility serves as:",opts:["The common connection point for all equipment grounding conductors","A spare neutral","A lightning rod","A communication bus"],ans:0,exp:"The ground bus provides a single low-impedance connection point for all equipment grounds, bonding conductors, and the grounding electrode. Essential for personnel safety and fault clearing.",type:"recall"},
  {id:58,cat:"C",q:"What is the advantage of medium-voltage (>1000V) distribution in large plants?",opts:["Simpler wiring","Lower current for the same power — smaller conductors, lower losses, longer distances","More colourful cables","Easier to work on"],ans:1,exp:"P = V×I: higher voltage = lower current for same power. 4160V or 13.8kV distribution allows smaller conductors, reduced I²R losses, and longer feeder runs in large facilities.",type:"recall"},
  {id:59,cat:"C",q:"When terminating medium-voltage cable (>1000V), what is critical?",opts:["Use standard wire nuts","Wrap with standard tape","Proper stress cones or termination kits to manage electrical stress at the insulation cutback","Use twist-on connectors"],ans:2,exp:"MV cable terminations require stress cones/grading kits to control the electrical field at the point where the insulation shield is cut back. Without them, electrical stress causes breakdown.",type:"procedure"},
  {id:60,cat:"C",q:"A thermal imaging scan of switchgear reveals a hot connection. What is the likely cause?",opts:["Normal operation","The breaker is new","The paint is too dark","Loose connection, corrosion, or overloaded conductor"],ans:3,exp:"Hot spots on connections indicate high resistance from loose bolts, corrosion, or undersized/overloaded conductors. High resistance = I²R heating = potential fire or failure.",type:"critical"},
  {id:61,cat:"C",q:"What is the purpose of a coordination study?",opts:["Ensure overcurrent devices trip in proper sequence — nearest device trips first","To plan the project schedule","To coordinate paint colours","To balance loads"],ans:0,exp:"Coordination studies ensure selective tripping: the device nearest the fault clears it while upstream devices stay closed. This minimizes the area affected by a fault.",type:"recall"},
  {id:62,cat:"C",q:"The insulation class of a transformer determines:",opts:["Its colour","Maximum safe operating temperature","Its physical size","Its voltage ratio"],ans:1,exp:"Insulation class (A=105°C, B=130°C, F=155°C, H=180°C) defines maximum winding temperature. Exceeding the class temperature drastically shortens transformer life.",type:"recall"},
  {id:63,cat:"C",q:"Transformer oil (mineral oil) serves what dual purpose?",opts:["Lubrication and cooling","Cleaning and protection","Electrical insulation and heat transfer (cooling)","Grounding and bonding"],ans:2,exp:"Transformer oil provides electrical insulation between windings and the tank, AND serves as a heat transfer medium to carry heat from windings to the tank walls and radiators.",type:"recall"},
  {id:64,cat:"C",q:"A delta-wye transformer provides what advantage for industrial loads?",opts:["Lower cost only","Only single-phase power","Higher voltage only","3-phase power plus a neutral for single-phase loads, and traps 3rd harmonics in the delta primary"],ans:3,exp:"Delta primary traps triplen harmonics (3rd, 9th...). Wye secondary provides neutral for L-N loads (120V or 277V). Most common industrial transformer configuration.",type:"recall"},
  {id:65,cat:"C",q:"What is the purpose of a Buchholz relay on an oil-filled transformer?",opts:["Detects gas generation from internal faults (arcing, overheating) in the transformer oil","Overcurrent protection","Voltage regulation","Cooling fan control"],ans:0,exp:"Buchholz relays detect gas bubbles produced by insulation breakdown inside the transformer. Slow accumulation triggers an alarm; sudden gas surge triggers an emergency trip.",type:"recall"},
  {id:66,cat:"C",q:"Cable derating is required when:",opts:["Cable is too expensive","Multiple cables are bundled together, ambient temperature exceeds 30°C, or cables are in high-heat areas","Cable is copper","Cable run is short"],ans:1,exp:"Bundling reduces heat dissipation (more cables = less cooling). High ambient temp reduces the temperature rise allowed. CEC tables provide specific derating factors.",type:"procedure"},
  {id:67,cat:"C",q:"A 600V rated industrial disconnect switch must be rated for:",opts:["Only the running current","Half the motor current","The full load current plus applicable CEC rules for motor disconnect sizing (115-250% of FLA)","Twice the building load"],ans:2,exp:"Motor disconnects must handle locked rotor current and be rated per CEC rules — typically 115% of FLA for general purpose, or sized to the next standard switch size.",type:"recall"},

  // ═══ BLOCK D: Motor Controls & Drives (28) ═══
  {id:68,cat:"D",q:"A NEMA Size 1 starter is rated for motors up to approximately:",opts:["5 HP at 480V","25 HP at 480V","50 HP at 480V","10 HP at 480V"],ans:3,exp:"NEMA sizes: 00=2HP, 0=5HP, 1=10HP, 2=25HP, 3=50HP, 4=100HP, 5=200HP (at 480V). Size 1 is the most common industrial starter size.",type:"recall"},
  {id:69,cat:"D",q:"What is the purpose of a control transformer in an MCC bucket?",opts:["Step down voltage to 120V for the control circuit (coils, lights, buttons)","Power the motor","Increase motor voltage","Filter harmonics"],ans:0,exp:"Control transformers step 480V or 600V down to 120V for the control circuit. This allows standard 120V pushbuttons, pilot lights, and contactor coils while the power circuit runs at higher voltage.",type:"recall"},
  {id:70,cat:"D",q:"An electronic overload relay protects against:",opts:["Short circuits","Overcurrent, single-phasing, phase imbalance, ground fault, and stall","Only overcurrent","Only overtemperature"],ans:1,exp:"Modern electronic overloads provide comprehensive protection: thermal overload modeling, phase loss, phase imbalance, ground fault, stall/jam detection, and under-current (pump dry run).",type:"recall"},
  {id:71,cat:"D",q:"A VFD's DC bus voltage for a 480V input is approximately:",opts:["480V DC","240V DC","680V DC (480 × √2)","960V DC"],ans:2,exp:"The VFD rectifier converts AC to DC. Peak DC voltage = Vpeak = Vrms × √2 = 480 × 1.414 = 678V ≈ 680V DC. This bus voltage is then inverted to variable frequency AC.",type:"critical"},
  {id:72,cat:"D",q:"What is the purpose of a dynamic braking resistor on a VFD?",opts:["To start the motor faster","To increase speed","To improve power factor","Dissipate regenerative energy when the motor decelerates, preventing DC bus overvoltage"],ans:3,exp:"When a motor decelerates, it acts as a generator feeding energy back to the DC bus. The braking resistor dissipates this energy as heat, preventing DC bus overvoltage trips.",type:"recall"},
  {id:73,cat:"D",q:"A reduced voltage autotransformer starter limits starting current to approximately:",opts:["65-80% of DOL depending on tap","50%","25%","100%"],ans:0,exp:"Autotransformer starters use taps (65%, 80%) to reduce voltage to the motor during starting. Current reduces proportionally to voltage. 80% tap = ~64% of DOL current (current reduces as voltage² for torque).",type:"critical"},
  {id:74,cat:"D",q:"When a VFD displays 'ground fault' trip, what should be checked?",opts:["Programming only","Motor insulation (megger test), motor cables for damage, and VFD output connections","The input fuses","The control transformer"],ans:1,exp:"Ground fault trip: megger the motor windings to ground, inspect motor cables for insulation damage (especially at terminations and through conduit), check connections at motor junction box.",type:"procedure"},
  {id:75,cat:"D",q:"A servo drive differs from a standard VFD in that it provides:",opts:["Only speed control","AC power only","Precise position, speed, and torque control with feedback (closed-loop)","No feedback capability"],ans:2,exp:"Servo drives use encoder/resolver feedback for precise closed-loop control of position, speed, and torque. They respond much faster than standard VFDs. Used in CNC, robotics, packaging.",type:"recall"},
  {id:76,cat:"D",q:"In a 3-wire control circuit, what provides low-voltage protection?",opts:["The fuse","The overload relay","The disconnect switch","The seal-in contact — motor won't restart automatically after power loss"],ans:3,exp:"In 3-wire control (start/stop buttons + seal-in), the seal-in contact drops out on power loss. The motor won't restart until someone presses start again = low-voltage PROTECTION.",type:"recall"},
  {id:77,cat:"D",q:"2-wire control (maintained contact) provides:",opts:["Low-voltage release — motor restarts automatically when power returns","Low-voltage protection","No restart capability","Manual restart only"],ans:0,exp:"2-wire control (pressure switch, float switch, thermostat) provides low-voltage RELEASE: the motor automatically restarts when power returns because the maintained contact is still closed.",type:"recall"},
  {id:78,cat:"D",q:"What must be installed on a VFD output to protect the motor from voltage spikes (dV/dt)?",opts:["A standard breaker","Output line reactor or dV/dt filter, especially on long cable runs","A bigger motor","Nothing is needed"],ans:1,exp:"VFD output waveform contains steep voltage spikes. Long cable runs amplify these (reflected wave effect), damaging motor insulation. Line reactors or dV/dt filters attenuate these spikes.",type:"recall"},
  {id:79,cat:"D",q:"A power contactor rated AC-3 is designed for:",opts:["Resistive heating loads","Transformer switching","Starting and stopping squirrel-cage motors under load","Capacitor switching"],ans:2,exp:"IEC utilization categories: AC-1 = resistive/slightly inductive. AC-3 = squirrel cage motor starting/stopping. AC-4 = plugging/jogging. AC-3 is the most common motor duty.",type:"recall"},
  {id:80,cat:"D",q:"What causes 'hunting' (oscillation around setpoint) in a motor speed control system?",opts:["Motor is too large","The motor is new","Voltage is too low","PID gains are too aggressive — typically too much proportional or integral action"],ans:3,exp:"Hunting/oscillation indicates the controller is overcorrecting. Reduce proportional gain first, then check integral. Derivative can help dampen oscillations. Proper PID tuning eliminates hunting.",type:"critical"},
  {id:81,cat:"D",q:"An inverter-duty motor differs from a standard motor in:",opts:["Enhanced insulation system to withstand VFD output voltage spikes and wider speed range cooling","Colour only","Higher HP rating","Lower cost"],ans:0,exp:"Inverter-duty motors have: reinforced insulation (handles dV/dt spikes), improved cooling for low-speed operation, and are designed for wide speed ranges. NEMA MG-1 Part 31 specifies requirements.",type:"recall"},
  {id:82,cat:"D",q:"Motor branch circuit protection (fuses/breaker) is sized at what percentage of FLA?",opts:["100%","150-300% depending on motor type and starter type per CEC Table 29","50%","80%"],ans:1,exp:"CEC Table 29 specifies maximum branch circuit protection: dual-element fuses typically 175% FLA, standard fuses 300%, inverse-time breakers 250%. This allows starting inrush without tripping.",type:"critical"},
  {id:83,cat:"D",q:"What does a current-limiting fuse do during a short circuit?",opts:["Blows slowly","Only protects against overloads","Interrupts the fault current before it reaches its full peak value, limiting let-through energy","Limits voltage"],ans:2,exp:"Current-limiting fuses melt and clear before the fault current reaches peak asymmetric value. This dramatically reduces let-through energy (I²t), protecting equipment and reducing arc flash hazard.",type:"recall"},
  {id:84,cat:"D",q:"A motor running at 1750 RPM on a 4-pole, 60Hz supply has a slip of:",opts:["1.4%","5.6%","0%","2.8%"],ans:3,exp:"Synchronous speed = 120×60÷4 = 1800 RPM. Slip = (1800-1750)÷1800 × 100 = 2.78% ≈ 2.8%. Typical slip for NEMA B motors is 2-4%.",type:"critical"},
  {id:85,cat:"D",q:"When meggering a VFD output, what precaution must be taken?",opts:["Disconnect the VFD from the motor leads — NEVER megger through a VFD","None","Increase test voltage","Test only one phase"],ans:0,exp:"The megger's high DC voltage will destroy the VFD's IGBT transistors. Always disconnect the motor cables from the VFD output terminals before meggering the motor.",type:"procedure"},
  {id:86,cat:"D",q:"What is regenerative braking?",opts:["Using mechanical brakes","The motor acts as a generator during deceleration, feeding energy back to the power source or a resistor","Reversing the motor to stop","Using a separate brake motor"],ans:1,exp:"During deceleration, the motor's inertia drives it faster than the rotating field, turning it into a generator. Energy flows back to the drive. Common in cranes, elevators, and centrifuges.",type:"recall"},
  {id:87,cat:"D",q:"A wound-rotor motor's external resistors are used to:",opts:["Increase line voltage","Heat the motor","Control starting torque and speed by adding resistance to the rotor circuit","Protect against overloads"],ans:2,exp:"External rotor resistors increase starting torque while limiting starting current. As the motor accelerates, resistance is stepped out. Also provides limited speed control below base speed.",type:"recall"},
  {id:88,cat:"D",q:"DC injection braking stops a motor by:",opts:["Reversing AC power","Disconnecting power","Using friction brakes only","Applying DC current to the stator windings, creating a stationary magnetic field that brakes the rotor"],ans:3,exp:"DC injection feeds DC to AC stator windings, creating a stationary magnetic field. The spinning rotor cuts this field, inducing currents that create braking torque. Motor stops without reversing.",type:"recall"},
  {id:89,cat:"D",q:"What is the function of a phase monitor relay?",opts:["Monitor for phase loss, phase reversal, and phase imbalance to protect 3-phase equipment","Count phases","Generate phases","Store energy"],ans:0,exp:"Phase monitor relays continuously check all three phases for: loss (single-phasing), reversal (wrong rotation), and voltage imbalance. They trip the control circuit to protect motors and equipment.",type:"recall"},
  {id:90,cat:"D",q:"When installing a VFD, the input and output cables should be:",opts:["Run together for convenience","Separated — input and output cables in separate raceways to prevent interference","Twisted together","In the same conduit always"],ans:1,exp:"VFD output cables carry high-frequency PWM noise. Running them with input or control cables causes interference. Use separate raceways and shielded cable for outputs when possible.",type:"procedure"},
  {id:91,cat:"D",q:"A synchronous motor runs at exactly synchronous speed because:",opts:["It has no slip","It's larger than other motors","Its rotor field is energized by DC, locking it to the rotating stator field","It uses brushes for AC"],ans:2,exp:"Synchronous motors have a DC-excited rotor that magnetically locks to the rotating stator field. Zero slip = exact synchronous speed. Also provides power factor correction.",type:"recall"},
  {id:92,cat:"D",q:"What does 'V/Hz' ratio mean in VFD operation?",opts:["Voltage divided by time","Speed setting","Power factor","Maintaining constant voltage-to-frequency ratio for constant motor flux and torque below base speed"],ans:3,exp:"Constant V/Hz maintains rated magnetic flux in the motor as frequency changes. Below base speed: both V and f change proportionally. Above base speed: V stays at max, f increases (field weakening).",type:"recall"},
  {id:93,cat:"D",q:"The most common cause of VFD failure is:",opts:["DC bus capacitor degradation due to heat and age","Lightning","Motor failure","Programming errors"],ans:0,exp:"Electrolytic DC bus capacitors degrade over time (5-10 year lifespan) due to heat, ripple current, and age. They dry out, lose capacitance, and ESR increases. Regular capacitor testing extends VFD life.",type:"recall"},
  {id:94,cat:"D",q:"A contactor's coil voltage must match:",opts:["The motor voltage","The control circuit voltage","The line voltage always","Any available voltage"],ans:1,exp:"The coil is powered by the control circuit, not the power circuit. If control voltage is 120V AC, the coil must be 120V AC. Using wrong coil voltage causes failure to pull in (low) or coil burnout (high).",type:"recall"},
  {id:95,cat:"D",q:"What is the maximum number of starts per hour for a typical large industrial motor?",opts:["Unlimited","50","Depends on motor thermal capacity — typically 2-4 for large motors","20"],ans:2,exp:"Each start generates enormous heat (5-7× FLA during startup). Large motors may be limited to 2-4 starts/hour. Exceeding this overheats windings. Check manufacturer data.",type:"recall"},

  // ═══ BLOCK E: PLCs & Automation (22) ═══
  {id:96,cat:"E",q:"A PLC scan cycle consists of:",opts:["Only running the program","Reading sensors only","Writing outputs only","Input scan → Program execution → Output scan → Housekeeping/communications"],ans:3,exp:"Each PLC scan: reads all inputs, executes the entire program, updates all outputs, then handles communications/diagnostics. Scan time is typically 1-100ms depending on program size.",type:"recall"},
  {id:97,cat:"E",q:"In ladder logic, an OTE (Output Energize) instruction:",opts:["Turns on when rung conditions are TRUE, turns off when FALSE","Is always on","Latches permanently","Is the same as an input"],ans:0,exp:"OTE is non-retentive: follows rung logic exactly. TRUE rung = output ON. FALSE rung = output OFF. Every scan re-evaluates. For latching, use OTL/OTU pair instead.",type:"recall"},
  {id:98,cat:"E",q:"What is the difference between OTL (Output Latch) and OTE?",opts:["No difference","OTL remains ON even when rung goes FALSE — requires OTU to unlatch","OTL is faster","OTE is permanent"],ans:1,exp:"OTL (latch) stays ON once energized, even if the rung goes FALSE. It remains latched through power cycles (retentive). Only an OTU (unlatch) instruction on the same address turns it OFF.",type:"recall"},
  {id:99,cat:"E",q:"A PLC counter instruction CTU counts:",opts:["Down only","Continuously","Up — increments accumulated value each FALSE-to-TRUE transition of the count input","Randomly"],ans:2,exp:"CTU (Count Up) increments the accumulator by 1 on each rising edge (FALSE→TRUE) of the input. When accumulated value reaches preset, the done bit (.DN) turns ON.",type:"recall"},
  {id:100,cat:"E",q:"What is the function of a PLC communication module?",opts:["Power the PLC","Run the program faster","Store the program only","Enable data exchange between the PLC and other devices (HMIs, drives, other PLCs, SCADA)"],ans:3,exp:"Communication modules support protocols like EtherNet/IP, Modbus, Profinet, DeviceNet — connecting PLCs to HMIs, VFDs, remote I/O, SCADA, and other PLCs for integrated automation.",type:"recall"},
  {id:101,cat:"E",q:"A safety PLC differs from a standard PLC by:",opts:["Dual-channel redundant processing and diagnostics meeting SIL/Category standards for safety functions","Colour only","Higher speed","More memory"],ans:0,exp:"Safety PLCs have redundant processors that cross-check each other, diagnostic coverage, and certified safety integrity levels (SIL) for E-stop, light curtain, and safety interlock functions.",type:"recall"},
  {id:102,cat:"E",q:"What does an HMI (Human Machine Interface) provide?",opts:["Motor starting only","Visual display of process data, alarms, and operator control interface for the automation system","Printer output only","PLC programming only"],ans:1,exp:"HMIs display process graphics, trend data, alarms, and provide touchscreen operator controls. They communicate with PLCs to show real-time process status and allow setpoint changes.",type:"recall"},
  {id:103,cat:"E",q:"In structured text (PLC programming), IF...THEN...ELSE is:",opts:["Not used in PLCs","A timer instruction","A conditional statement that executes code based on whether a condition is TRUE or FALSE","A counter"],ans:2,exp:"Structured Text (IEC 61131-3) uses programming constructs like IF/THEN/ELSE, FOR/DO, WHILE/DO, and CASE statements. It's powerful for complex math and decision-making logic.",type:"recall"},
  {id:104,cat:"E",q:"A PLC forcing an output ON bypasses normal program logic. When is this acceptable?",opts:["Anytime during production","Never","Whenever convenient","Only during commissioning/troubleshooting with proper safety procedures and documentation"],ans:3,exp:"Forcing bypasses program safety logic — extremely dangerous in production. Only during commissioning/troubleshooting with proper lockout, a spotter on the equipment, and forces must be removed after.",type:"procedure"},
  {id:105,cat:"E",q:"EtherNet/IP uses what type of physical network?",opts:["Standard Ethernet (Cat5e/Cat6) infrastructure with TCP/IP and CIP protocol","Serial RS-232","Coaxial cable only","Fibre only"],ans:0,exp:"EtherNet/IP runs on standard Ethernet hardware (switches, Cat5e/6 cable) using TCP/IP for configuration and UDP/IP for real-time I/O data. CIP (Common Industrial Protocol) is the application layer.",type:"recall"},
  {id:106,cat:"E",q:"A PLC program has a rung with XIC B3:0/0 and XIO B3:0/1 in series driving OTE O:2/0. When does the output turn ON?",opts:["When both bits are 1","When B3:0/0 is 1 AND B3:0/1 is 0","When B3:0/0 is 0","When B3:0/1 is 1"],ans:1,exp:"XIC (Examine If Closed) is TRUE when the bit is 1. XIO (Examine If Open) is TRUE when the bit is 0. Both must be TRUE (series = AND logic) for the output to energize.",type:"critical"},
  {id:107,cat:"E",q:"What is a PLC's I/O addressing system?",opts:["Email addresses","IP addresses","A structured numbering scheme that maps physical I/O points to memory locations in the program","Phone numbers"],ans:2,exp:"I/O addressing maps each physical input and output terminal to a specific memory location. Example: I:1/0 = Input module slot 1, terminal 0. Addressing varies by PLC manufacturer.",type:"recall"},
  {id:108,cat:"E",q:"A function block diagram (FBD) PLC language uses:",opts:["Contacts and coils","C++ code","Assembly language","Interconnected graphical blocks representing functions (AND, OR, timers, PID, math)"],ans:3,exp:"FBD uses graphical blocks with inputs on the left and outputs on the right, connected by signal flow lines. Great for process control, analog processing, and continuous function applications.",type:"recall"},
  {id:109,cat:"E",q:"What is the purpose of a watchdog timer in a PLC?",opts:["Detect if the PLC scan takes too long (indicating a fault) and trigger a safe shutdown","Time process events","Count parts","Set the clock"],ans:0,exp:"The watchdog timer monitors scan time. If a scan exceeds the configured limit (program hang, hardware fault), the PLC faults to a safe state to prevent uncontrolled operation.",type:"recall"},
  {id:110,cat:"E",q:"In PLC analog I/O, a 12-bit resolution provides how many discrete steps?",opts:["256","4096","1024","65536"],ans:1,exp:"2^12 = 4096 steps. For a 4-20mA input mapped to 0-100%, each step = 100/4096 = 0.024%. Higher resolution (16-bit = 65,536 steps) provides finer measurement granularity.",type:"critical"},
  {id:111,cat:"E",q:"A PLC program should scan critical safety inputs:",opts:["Once per minute","Only when needed","Every scan — safety inputs must never be buffered or conditional","Every 10 scans"],ans:2,exp:"Safety-critical inputs (E-stops, guard switches, safety relays) must be scanned every cycle with no conditional bypassing. They should be wired to dedicated safety inputs where possible.",type:"procedure"},
  {id:112,cat:"E",q:"What is the purpose of PLC battery backup?",opts:["Power the outputs","Run the motor","Charge the HMI","Maintain program and data memory during power loss for non-flash-based PLCs"],ans:3,exp:"Battery maintains volatile RAM contents (program, data, retentive values) during power off. Flash-based PLCs retain programs without battery. Low battery warnings must be addressed promptly.",type:"recall"},
  {id:113,cat:"E",q:"A SCADA system polls a remote PLC for data every 5 seconds. This is called:",opts:["Polling or scan-based communication","Real-time control","Handshaking","Broadcasting"],ans:0,exp:"SCADA polling: the master station cyclically requests data from remote devices at a configured interval. Faster polling = more current data but higher network traffic.",type:"recall"},
  {id:114,cat:"E",q:"DeviceNet is an industrial network designed primarily for:",opts:["Long-distance data transfer","Device-level communication between PLCs, sensors, actuators, and drives","Office networking","Internet access"],ans:1,exp:"DeviceNet is a CAN-based device-level network connecting sensors, actuators, motor starters, VFDs, and valves to a PLC. Designed for short messages and fast response at the device level.",type:"recall"},
  {id:115,cat:"E",q:"What is the benefit of remote I/O in a large facility?",opts:["Eliminates the PLC","Increases wire count","Reduces wiring by placing I/O modules near field devices and communicating digitally to the PLC","Slows down the system"],ans:2,exp:"Remote I/O eliminates long home-run wiring. I/O racks near the equipment connect to the PLC over a single network cable, reducing installation cost, troubleshooting time, and wire tray fill.",type:"recall"},
  {id:116,cat:"E",q:"A PLC MOV (Move) instruction does what?",opts:["Physically moves the PLC","Moves a conveyor","Deletes data","Copies data from a source address to a destination address in PLC memory"],ans:3,exp:"MOV copies the value from the source operand to the destination operand. The source is unchanged. Used to load setpoints, transfer data between registers, and set values.",type:"recall"},
  {id:117,cat:"E",q:"When replacing a PLC processor, what must be done first?",opts:["Back up the program, document I/O forcing, and verify the replacement processor is compatible","Just plug the new one in","Paint the cabinet","Upgrade the HMI"],ans:0,exp:"Before swapping: back up the program and configuration, document any forces or overrides, verify firmware compatibility, and have the program ready to download to the new processor.",type:"procedure"},

  // ═══ BLOCK F: Maintenance & Troubleshooting (18) ═══
  {id:118,cat:"F",q:"A motor is tripping on overload intermittently. What should be checked first?",opts:["Replace the motor","Check actual current draw vs nameplate FLA, check for mechanical binding, and verify overload setting","Replace the starter","Check the paint"],ans:1,exp:"Measure running amps on all phases. Compare to nameplate FLA. Check for: mechanical load issues, phase imbalance, loose connections, ventilation blockage, overload set too low.",type:"procedure"},
  {id:119,cat:"F",q:"Vibration analysis on a motor shows a peak at 2× line frequency (120Hz). This indicates:",opts:["Imbalance","Misalignment","Electrical issue — likely unequal air gap, broken rotor bar, or electrical imbalance","Looseness"],ans:2,exp:"2× line frequency (120Hz on 60Hz systems) is characteristic of electromagnetic forces: eccentric rotor (unequal air gap), broken rotor bars, shorted stator turns, or supply voltage imbalance.",type:"critical"},
  {id:120,cat:"F",q:"When troubleshooting a control circuit, you measure 120V across a contactor coil but it won't pull in. What's the issue?",opts:["Voltage is too high","The voltage is normal, no problem","The control transformer is bad","The coil is open (burned out) — voltage present but no current flows through an open coil"],ans:3,exp:"Voltage across an open component = source voltage (voltage divider with infinite resistance). The coil has failed open-circuit. Replace the contactor or coil. Measure current to confirm.",type:"critical"},
  {id:121,cat:"F",q:"An insulation resistance test (megger) on a motor reads 0.5 MΩ. What action should be taken?",opts:["Investigate — reading is low. Check for moisture, contamination, or degraded insulation","Motor is fine","Replace immediately","Increase voltage"],ans:0,exp:"0.5 MΩ is below the minimum acceptable (typically 1MΩ + 1MΩ/kV). Investigate: dry out the motor (space heaters), clean contamination, or test further. Trend declining values indicate impending failure.",type:"procedure"},
  {id:122,cat:"F",q:"A VFD shows an 'overvoltage' fault on deceleration. What is the cause?",opts:["Input voltage too high","Regenerative energy from the motor raising the DC bus voltage above the trip point","Programming error","Motor too small"],ans:1,exp:"During deceleration, motor regenerates energy back to the DC bus. If the decel ramp is too fast and no braking resistor is installed, the bus voltage exceeds the overvoltage trip threshold. Lengthen decel time or add braking resistor.",type:"critical"},
  {id:123,cat:"F",q:"When a 3-phase motor hums but doesn't start, the most likely cause is:",opts:["Low oil level","Motor is too large","Single-phasing — one phase is lost (blown fuse, broken wire, bad contactor contact)","Foundation is loose"],ans:2,exp:"A 3-phase motor with one phase missing cannot develop starting torque — it just hums loudly and draws high current. Check all 3 phases at the motor terminals. Common cause: one contactor contact failed.",type:"critical"},
  {id:124,cat:"F",q:"Thermography on an MCC shows one starter significantly hotter than adjacent units. Investigation should focus on:",opts:["Repainting the unit","The MCC colour scheme","The room temperature","Loose connections, overloaded circuit, or high-resistance contacts inside the starter"],ans:3,exp:"Hot spots in MCCs: loose bus connections, undersized conductors, corroded/pitted contactor contacts, overloaded circuit, or poor ventilation. Thermal imaging catches problems before failure.",type:"procedure"},
  {id:125,cat:"F",q:"A motor bearing failure is best detected early using:",opts:["Vibration analysis showing bearing defect frequencies (BPFO, BPFI, BSF, FTF)","Visual inspection","Resistance measurement","Voltage measurement"],ans:0,exp:"Vibration analysis detects bearing defects months before failure by identifying characteristic frequencies. Ultrasonic testing detects even earlier-stage defects. Together they enable planned replacement.",type:"recall"},
  {id:126,cat:"F",q:"An electrical circuit breaker trips repeatedly after being reset. The correct approach is:",opts:["Hold it in the ON position","Do NOT force — investigate the cause. Check for short circuits, ground faults, or overloads","Replace with a larger breaker","Tape it in position"],ans:1,exp:"A tripping breaker indicates a fault. Investigate: check motor/load for short circuit, check wiring for ground fault, verify load doesn't exceed breaker rating. Never upsize without engineering review.",type:"procedure"},
  {id:127,cat:"F",q:"Motor winding resistance should be approximately equal on all three phases. An imbalance greater than what percentage indicates a problem?",opts:["10%","25%","2% (or more than a few percent difference)","50%"],ans:2,exp:"Phase-to-phase winding resistance should be within 1-2% of each other. Greater imbalance indicates: shorted turns, poor connections, or unequal conductor lengths. Use a low-resistance ohmmeter.",type:"recall"},
  {id:128,cat:"F",q:"A PLC input LED is ON but the program doesn't see the input. What should be checked?",opts:["The output module","The power supply only","The network cable","The input module hardware, wiring connection, and whether the correct PLC address is being monitored"],ans:3,exp:"LED ON means the field device is providing signal. If the PLC program doesn't register it: check if you're monitoring the correct address, check the input module for fault, verify the slot/channel mapping.",type:"procedure"},
  {id:129,cat:"F",q:"Preventive maintenance on a VFD should include:",opts:["Cleaning cooling fans/heatsinks, checking connections, inspecting DC bus capacitors, and verifying fan operation","Repainting the enclosure","Only reading the display","Nothing until it fails"],ans:0,exp:"VFD PM: clean fans and heatsinks (dust reduces cooling), retorque connections, inspect capacitors for bulging/leaking, verify fan operation, check for error logs, and update firmware as recommended.",type:"procedure"},
  {id:130,cat:"F",q:"A ground fault on a 3-phase ungrounded delta system — the first fault causes:",opts:["A trip","No trip — but one phase now has 0V to ground and the other two have full line voltage to ground","An explosion","Nothing at all"],ans:1,exp:"On ungrounded delta, the first ground fault doesn't trip anything (no ground return path). But it elevates the other two phases to full line-to-line voltage to ground, stressing insulation. A second ground fault on another phase creates a phase-to-phase short.",type:"critical"},
  {id:131,cat:"F",q:"How is a transformer's turns ratio verified in the field?",opts:["By visual inspection","By weighing the transformer","Measure primary and secondary voltages — the ratio should match the nameplate","By measuring oil level"],ans:2,exp:"Apply known voltage to primary, measure secondary voltage. Ratio = V1/V2 should equal the nameplate turns ratio. Also verify tap changer position matches expected ratio.",type:"procedure"},
  {id:132,cat:"F",q:"Cable fault locating using TDR (Time Domain Reflectometry) works by:",opts:["Applying high voltage","Measuring temperature","Using X-rays","Sending a pulse and measuring the time for the reflection to return from the fault"],ans:3,exp:"TDR sends an electrical pulse down the cable. Discontinuities (opens, shorts, splices) reflect part of the pulse. The round-trip time × propagation velocity ÷ 2 = distance to fault.",type:"recall"},
  {id:133,cat:"F",q:"A motor running hot but drawing normal amps likely has:",opts:["A cooling problem — blocked ventilation, failed cooling fan, or dirty motor","An electrical problem","A control circuit issue","Too much grease"],ans:0,exp:"Normal amps = normal electrical loading. Overheating with normal current points to cooling deficiency: clogged air passages, failed external fan, high ambient temperature, or excessive regreasing blocking air paths.",type:"critical"},
  {id:134,cat:"F",q:"What does a hi-pot (high potential) test verify?",opts:["Motor speed","The integrity of insulation to withstand higher-than-normal voltage without breakdown","Wire size","Connection torque"],ans:1,exp:"Hi-pot testing applies voltage higher than rated (typically 2× rated + 1000V) to verify insulation integrity. It's a go/no-go test — insulation either withstands or breaks down. Performed on new installations.",type:"recall"},
  {id:135,cat:"F",q:"The correct sequence for troubleshooting an industrial electrical fault is:",opts:["Replace everything","Just reset the breaker","Observe symptoms → analyze/isolate → test to confirm → repair → verify operation","Call the manufacturer first"],ans:2,exp:"Systematic troubleshooting: (1) Observe symptoms and collect data, (2) Analyze and narrow down possible causes, (3) Test to isolate the fault, (4) Repair/replace, (5) Verify correct operation and document.",type:"procedure"},
];
